// The Alpine minirootfs may not ship device nodes. In fakefs these are
// metadata backed by regular host files, not host device creation.
static int ensure_guest_mem_device(const char *path, int minor) {
    struct statbuf stat;
    dev_t_ device = dev_make(MEM_MAJOR, minor);
    int rc = generic_statat(AT_PWD, path, &stat, false);
    if (rc == _ENOENT) {
        rc = generic_mknodat(AT_PWD, path, S_IFCHR|0666, device);
        if (rc < 0)
            return rc;
        rc = generic_statat(AT_PWD, path, &stat, false);
    }
    if (rc < 0)
        return rc;
    if (!S_ISCHR(stat.mode) || stat.rdev != device)
        return _EINVAL;
    return 0;
}

int ish_ffi_mount_devpts(void) {
    if (current == NULL)
        return -EINVAL;
    // All four use the existing emulated memory device drivers. Random
    // reads call the existing platform CSPRNG; never substitute dummy data.
    int rc = ensure_guest_mem_device("/dev/null", DEV_NULL_MINOR);
    if (rc < 0) return rc;
    rc = ensure_guest_mem_device("/dev/zero", DEV_ZERO_MINOR);
    if (rc < 0) return rc;
    rc = ensure_guest_mem_device("/dev/random", DEV_RANDOM_MINOR);
    if (rc < 0) return rc;
    rc = ensure_guest_mem_device("/dev/urandom", DEV_URANDOM_MINOR);
    if (rc < 0) return rc;
    generic_mknodat(AT_PWD, "/dev/ptmx", S_IFCHR|0666,
                    dev_make(TTY_ALTERNATE_MAJOR, DEV_PTMX_MINOR));

