fn drain_session_output(sessions: &mut HashMap<u32, Session>, reqid: u32) -> io::Result<()> {
    // Take the session out so we can call write_frame (which borrows
    // global stdout) without overlapping mutable borrows.
    let Some(s) = sessions.get_mut(&reqid) else {
        return Ok(());
    };
    let stream = s.stream;
    let mut buf = [0u8; OUTPUT_CHUNK];
    loop {
        let n = unsafe {
            libc::read(
                s.output_fd(),
                buf.as_mut_ptr() as *mut libc::c_void,
                buf.len(),
            )
        };
        if n > 0 {
            let seq = s.next_seq;
            s.next_seq += 1;
            let frame = SupervisorToHost::Output {
                reqid,
                seq,
                stream,
                bytes: buf[..n as usize].to_vec(),
            };
            write_frame(&frame)?;
            continue;
        }
        if n == 0 {
            s.eof = true;
            return Ok(());
        }
        // n < 0
        let err = io::Error::last_os_error();
        match err.kind() {
            io::ErrorKind::WouldBlock => return Ok(()),
            io::ErrorKind::Interrupted => continue,
            _ => {
                // For pty masters, EIO is the canonical "child closed all
                // slave references" signal.
                if err.raw_os_error() == Some(libc::EIO) {
                    s.eof = true;
                    return Ok(());
                }
                return Err(err);
            }
        }
    }
}

fn drain_session_output(sessions: &mut HashMap<u32, Session>, reqid: u32) -> io::Result<()> {
    let Some(s) = sessions.get_mut(&reqid) else { return Ok(()); };
    if !s.eof {
        let fd = s.output_fd();
        s.eof = drain_output_fd(reqid, fd, s.stream, &mut s.next_seq)?;
    }
    if !s.stderr_eof {
        if let Some(fd) = &s.stderr {
            s.stderr_eof = drain_output_fd(reqid, fd.as_raw_fd(), ish_embed_protocol::Stream::Stderr, &mut s.next_seq)?;
        }
    }
    Ok(())
}

// Limit each drain pass so a continuously producing stream cannot starve
// the other stream or the supervisor's control messages.
fn drain_output_fd(reqid: u32, fd: RawFd, stream: ish_embed_protocol::Stream, next_seq: &mut u64) -> io::Result<bool> {
    let mut buf = [0u8; OUTPUT_CHUNK];
    for _ in 0..8 {
        let n = unsafe { libc::read(fd, buf.as_mut_ptr() as *mut libc::c_void, buf.len()) };
        if n > 0 {
            let seq = *next_seq;
            *next_seq += 1;
            write_frame(&SupervisorToHost::Output { reqid, seq, stream, bytes: buf[..n as usize].to_vec() })?;
            continue;
        }
        if n == 0 { return Ok(true); }
        let err = io::Error::last_os_error();
        match err.kind() {
            io::ErrorKind::WouldBlock => return Ok(false),
            io::ErrorKind::Interrupted => continue,
            _ if matches!(stream, ish_embed_protocol::Stream::Pty) && err.raw_os_error() == Some(libc::EIO) => return Ok(true),
            _ => return Err(err),
        }
    }
    Ok(false)
}

